// parseBundle fully validates a bundle body and, on success, returns the
// object ready to store. On failure it returns the error code and HTTP
// status to report; the store is never touched on the failure path.
func parseBundle(body []byte) (obj *object, code string, status int) {
	invalid := func() (*object, string, int) {
		return nil, "invalid_bundle", http.StatusBadRequest
	}
	integrity := func() (*object, string, int) {
		return nil, "integrity_check_failed", http.StatusUnprocessableEntity
	}

	if !wellFormedJSON(body) {
		return invalid()
	}
	var doc bundleJSON
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&doc); err != nil {
		return invalid()
	}
	if doc.Version == nil || doc.Root == nil || doc.Blocks == nil ||
		doc.Root.CID == nil || doc.Root.Size == nil || doc.Root.ChunkSize == nil ||
		doc.Root.Chunks == nil {
		return invalid()
	}
	for _, b := range *doc.Blocks {
		if b.CID == nil || b.Data == nil {
			return invalid()
		}
	}

	// Numeric fields must be integers. An integer outside int64 range is a
	// value problem, not a type problem: it cannot match a supported
	// version, chunk size or size limit.
	version, err := parseInt(*doc.Version)
	if err != nil {
		if errors.Is(err, strconv.ErrRange) {
			return nil, "unsupported_bundle", http.StatusUnprocessableEntity
		}
		return invalid()
	}
	chunkSize, err := parseInt(*doc.Root.ChunkSize)
	if err != nil {
		if errors.Is(err, strconv.ErrRange) {
			return nil, "unsupported_bundle", http.StatusUnprocessableEntity
		}
		return invalid()
	}
	size, err := parseInt(*doc.Root.Size)
	if err != nil {
		if errors.Is(err, strconv.ErrRange) {
			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
		}
		return invalid()
	}

	if !validCID(*doc.Root.CID) {
		return invalid()
	}
	for _, c := range *doc.Root.Chunks {
		if !validCID(c) {
			return invalid()
		}
	}
	blockData := make(map[string][]byte, len(*doc.Blocks))
	for _, b := range *doc.Blocks {
		if !validCID(*b.CID) {
			return invalid()
		}
		data, err := base64.StdEncoding.DecodeString(*b.Data)
		if err != nil {
			return invalid()
		}
		blockData[*b.CID] = data
	}

	if version != bundleVersion || chunkSize != ChunkSize {
		return nil, "unsupported_bundle", http.StatusUnprocessableEntity
	}
	if size > MaxObjectSize {
		return nil, "payload_too_large", http.StatusRequestEntityTooLarge
	}
	if size < 0 {
		return integrity()
	}

	// The block set must be exactly the unique identifiers the manifest
	// references: no duplicates, none missing, none unreferenced.
	referenced := make(map[string]bool, len(*doc.Root.Chunks))
	for _, c := range *doc.Root.Chunks {
		referenced[c] = true
	}
	seen := make(map[string]bool, len(*doc.Blocks))
	for _, b := range *doc.Blocks {
		if seen[*b.CID] {
			return integrity()
		}
		seen[*b.CID] = true
		if !referenced[*b.CID] {
			return integrity()
		}
	}
	for c := range referenced {
		if !seen[c] {
			return integrity()
		}
	}

	// Every block identifier must be the digest of its decoded bytes.
	for cid, data := range blockData {
		if chunkCID(data) != cid {
			return integrity()
		}
	}

	// Rebuild the body in manifest order under the fixed chunking rules:
	// every chunk but the last is exactly ChunkSize, the last is 1..ChunkSize,
	// and an empty object carries no chunks at all.
	chunks := *doc.Root.Chunks
	if size == 0 && len(chunks) != 0 {
		return integrity()
	}
	if size > 0 && len(chunks) == 0 {
		return integrity()
	}
	total := 0
	for i, c := range chunks {
		n := len(blockData[c])
		if i < len(chunks)-1 {
			if n != ChunkSize {
				return integrity()
			}
		} else if n < 1 || n > ChunkSize {
			return integrity()
		}
		total += n
	}
	if total > MaxObjectSize {
		return nil, "payload_too_large", http.StatusRequestEntityTooLarge
	}
	if total != size {
		return integrity()
	}
	if rootCID(size, chunks) != *doc.Root.CID {
		return integrity()
	}

	obj = &object{
		cid:    *doc.Root.CID,
		size:   size,
		chunks: make([][]byte, 0, len(chunks)),
		cids:   append([]string{}, chunks...),
	}
	for _, c := range chunks {
		obj.chunks = append(obj.chunks, blockData[c])
	}
	return obj, "", 0
}

// wellFormedJSON reports whether data is a single well-formed JSON value
// with no duplicate object keys and nothing but whitespace after it.
func wellFormedJSON(data []byte) bool {
	dec := json.NewDecoder(bytes.NewReader(data))
	var walk func() bool
	walk = func() bool {
		tok, err := dec.Token()
		if err != nil {
			return false
		}
		delim, ok := tok.(json.Delim)
		if !ok {
			return true
		}
		switch delim {
		case '{':
			seen := make(map[string]bool)
			for dec.More() {
				key, err := dec.Token()
				if err != nil {
					return false
				}
				name, ok := key.(string)
				if !ok || seen[name] {
					return false
				}
				seen[name] = true
				if !walk() {
					return false
				}
			}
			_, err := dec.Token()
			return err == nil
		case '[':
			for dec.More() {
				if !walk() {
					return false
				}
			}
			_, err := dec.Token()
			return err == nil
		}
		return false
	}
	if !walk() {
		return false
	}
	_, err := dec.Token()
	return err == io.EOF
}

// parseInt converts a raw JSON value to an int, rejecting strings,
// non-numeric literals and fractional values as syntax errors.
func parseInt(raw json.RawMessage) (int, error) {
	if len(raw) == 0 || raw[0] == '"' {
		return 0, strconv.ErrSyntax
	}
	v, err := strconv.ParseInt(string(raw), 10, 0)
	if err != nil {
		return 0, err
	}
	return int(v), nil
}

// Package server exposes the frozen public surface of CidVault.
//
// The baseline only reports process health. Later work adds the capabilities
// described in README.md; keep the exported surface here backward compatible.
package server

import (
	"encoding/json"
	"net/http"
)

// Version is the baseline release identifier.
const Version = "0.1.0"

type health struct {
	Status  string `json:"status"`
	Service string `json:"service"`
	Version string `json:"version"`
}

// Handler returns the HTTP surface served by the baseline.
func Handler() http.Handler {
	objects := newStore()
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "cidvault", Version: Version})
	})
	mux.HandleFunc("/v1/objects", objects.postObject)
	mux.HandleFunc("/v1/objects/{cid}", objects.getObject)
	mux.HandleFunc("/v1/objects/{cid}/manifest", objects.getManifest)
	mux.HandleFunc("/v1/blocks/{cid}", objects.getBlockByID)
	mux.HandleFunc("/v1/bundles", objects.postBundle)
	mux.HandleFunc("/v1/bundles/{cid}", objects.getBundle)
	mux.HandleFunc("/v1/storage/stats", objects.getStorageStats)
	mux.HandleFunc("/v1/pins", objects.getPins)
	mux.HandleFunc("/v1/pins/{cid}", objects.pinByID)
	mux.HandleFunc("/v1/gc", objects.gc)
	return mux
}

