1	package server
2	
3	import (
4		"encoding/json"
5		"io"
6		"mime"
7		"net/http"
8		"strconv"
9	)
10	
11	// objectResponse is the JSON body returned by POST /v1/objects.
12	type objectResponse struct {
13		CID       string   `json:"cid"`
14		Size      int      `json:"size"`
15		ChunkSize int      `json:"chunkSize"`
16		Chunks    []string `json:"chunks"`
17		Created   bool     `json:"created"`
18	}
19	
20	// manifestResponse is the JSON body of GET /v1/objects/{cid}/manifest.
21	type manifestResponse struct {
22		CID       string   `json:"cid"`
23		Size      int      `json:"size"`
24		ChunkSize int      `json:"chunkSize"`
25		Chunks    []string `json:"chunks"`
26	}
27	
28	func writeJSON(w http.ResponseWriter, status int, body any) {
29		w.Header().Set("Content-Type", "application/json")
30		w.WriteHeader(status)
31		_ = json.NewEncoder(w).Encode(body)
32	}
33	
34	func writeError(w http.ResponseWriter, status int, code string) {
35		writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
36	}
37	
38	// postObject handles POST /v1/objects.
39	func (s *store) postObject(w http.ResponseWriter, r *http.Request) {
40		if r.Method != http.MethodPost {
41			w.Header().Set("Allow", http.MethodPost)
42			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
43			return
44		}
45		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
46		if err != nil || mediaType != "application/octet-stream" {
47			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
48			return
49		}
50		body, err := io.ReadAll(io.LimitReader(r.Body, MaxObjectSize+1))
51		if err != nil {
52			writeError(w, http.StatusBadRequest, "invalid_request")
53			return
54		}
55		if len(body) > MaxObjectSize {
56			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
57			return
58		}
59	
60		obj := &object{size: len(body), chunks: [][]byte{}, cids: []string{}}
61		for start := 0; start < len(body); start += ChunkSize {
62			end := start + ChunkSize
63			if end > len(body) {
64				end = len(body)
65			}
66			chunk := body[start:end]
67			obj.chunks = append(obj.chunks, chunk)
68			obj.cids = append(obj.cids, chunkCID(chunk))
69		}
70		obj.cid = rootCID(obj.size, obj.cids)
71	
72		stored, created := s.put(obj)
73		status := http.StatusOK
74		if created {
75			status = http.StatusCreated
76		}
77		writeJSON(w, status, objectResponse{
78			CID:       stored.cid,
79			Size:      stored.size,
80			ChunkSize: ChunkSize,
81			Chunks:    stored.cids,
82			Created:   created,
83		})
84	}
85	
86	// lookupObject validates the path identifier and resolves the object,
87	// writing the appropriate error response on failure.
88	func (s *store) lookupObject(w http.ResponseWriter, r *http.Request) *object {
89		cid := r.PathValue("cid")
90		if !validCID(cid) {
91			writeError(w, http.StatusBadRequest, "invalid_cid")
92			return nil
93		}
94		obj := s.get(cid)
95		if obj == nil {
96			writeError(w, http.StatusNotFound, "object_not_found")
97			return nil
98		}
99		return obj
100	}
101	
102	// getObject handles GET /v1/objects/{cid}.
103	func (s *store) getObject(w http.ResponseWriter, r *http.Request) {
104		if r.Method != http.MethodGet {
105			w.Header().Set("Allow", http.MethodGet)
106			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
