	sharedCID := chunkCID(shared)
	rec := exportDelta(t, hA, upA.CID, haveBody(t, []string{sharedCID}), "application/json")
	doc := decodeBundle(t, rec)
	if len(doc.Blocks) != 1 || doc.Blocks[0].CID == sharedCID {
